def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = 4

    # Find the full-length, non-background divider.
    line = None
    for r, row in enumerate(grid):
        if row[0] != bg and all(x == row[0] for x in row):
            line = ("h", r)
            break
    if line is None:
        for c in range(w):
            if grid[0][c] != bg and all(grid[r][c] == grid[0][c] for r in range(h)):
                line = ("v", c)
                break

    if line is None:
        return [row[:] for row in grid]

    orientation, pos = line
    obj = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] != bg and (r != pos if orientation == "h" else c != pos)]
    if not obj:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]

    if orientation == "h":
        lo, hi = min(r for r, _, _ in obj), max(r for r, _, _ in obj)
        if hi < pos:
            shift = pos - 1 - hi
            stripe = lo + shift - 1
        else:
            shift = pos + 1 - lo
            stripe = hi + shift + 1
        for r, c, _ in obj:
            out[r][c] = bg
        for r, c, color in obj:
            out[r + shift][c] = color
        if 0 <= stripe < h:
            out[stripe] = [8] * w
    else:
        lo, hi = min(c for _, c, _ in obj), max(c for _, c, _ in obj)
        if hi < pos:
            shift = pos - 1 - hi
            stripe = lo + shift - 1
        else:
            shift = pos + 1 - lo
            stripe = hi + shift + 1
        for r, c, _ in obj:
            out[r][c] = bg
        for r, c, color in obj:
            out[r][c + shift] = color
        if 0 <= stripe < w:
            for r in range(h):
                out[r][stripe] = 8

    return out
